const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const root=path.resolve(__dirname,'..');
test('Prefabs routes and catalog assets survive shared releases',()=>{const routes=JSON.parse(fs.readFileSync(path.join(root,'vercel.json'))).rewrites;for(const source of ['/sets','/sets/:path*','/scene-generator/prefabs','/scene-generator/prefabs/:path*'])assert(routes.some(r=>r.source===source&&r.destination==='/sets.html'),source);for(const p of ['sets.html','sets.js','sets-viewer.js','vendor/loaders/GLTFLoader.js','vendor/utils/BufferGeometryUtils.js'])assert(fs.existsSync(path.join(root,p)),p);const catalog=JSON.parse(fs.readFileSync(path.join(root,'sets-data/catalog.json')));let checked=0;function walk(v){if(!v||typeof v!=='object')return;for(const [k,x]of Object.entries(v)){if(['model','preview','metadata'].includes(k)&&typeof x==='string'&&x.startsWith('/')){assert(fs.existsSync(path.join(root,x.slice(1))),x);checked++;}else walk(x)}}walk(catalog);assert(checked>100);});
